SELECT r.role_id roleId, COUNT(DISTINCT a.account_id) employeeCount FROM t_role r LEFT JOIN t_tenant_member_role g ON g.role_id=r.role_id AND g.role_scope_key=r.scope_key AND g.status='ACTIVE' AND (g.effective_to IS NULL OR g.effective_to > UTC_TIMESTAMP(6)) LEFT JOIN t_tenant_member m ON m.member_id=g.tenant_member_id AND m.tenant_id=g.tenant_id AND m.status IN ('ACTIVE', 'SUSPENDED') AND m.tenant_id=( SELECT tenant_id FROM t_access_tenant WHERE tenant_type='INTERNAL' AND owner_ref_id=1 ) LEFT JOIN t_user_account a ON a.account_id=m.account_id AND a.realm='OPERATIONS' AND a.account_type='HUMAN' WHERE r.status='ACTIVE' AND AND r.role_id IN
#{roleId}
GROUP BY r.role_id ORDER BY r.role_id

SELECT g.tenant_member_id memberId, r.role_id roleId, r.role_code code, r.role_name name, r.system_role systemRole, r.version, (r.tenant_scope='PLATFORM') platformRole FROM t_tenant_member_role g JOIN t_role r ON r.role_id=g.role_id AND r.scope_key=g.role_scope_key WHERE g.tenant_member_id IN
#{memberId}
AND ORDER BY g.tenant_member_id, r.role_code, r.role_id

mapper.update:
UPDATE t_tenant_member
SET version=version+1, update_time=#{now}
WHERE member_id=#{id}
AND version=#{version}

UPDATE t_tenant_member_role
SET status='REVOKED', effective_to=CASE WHEN effective_from<#{now} THEN #{now} ELSE effective_to END,
version=version+1, update_time=#{now}
WHERE tenant_member_id=#{memberId}
AND status='ACTIVE'

UPDATE t_tenant_member_role g
JOIN t_role r ON r.role_id=g.role_id AND r.scope_key=g.role_scope_key
SET g.effective_to=NULL, g.granted_by=#{actorId}, g.status='ACTIVE',
    g.version=g.version+1, g.update_time=#{now}
WHERE g.tenant_member_id=#{memberId}
AND g.tenant_id=#{tenantId}
AND g.role_id=#{roleId}
AND g.effective_from=#{now}
AND g.status='REVOKED'
AND ((r.tenant_scope='PLATFORM' AND r.tenant_id IS NULL AND r.scope_key='PLATFORM')
    OR (r.tenant_scope='TENANT' AND r.tenant_id=#{tenantId} AND r.scope_key=CAST(#{tenantId} AS CHAR)))

