mapper.update:
UPDATE t_role
SET role_name=#{name}, version=version+1, update_time=#{now}
WHERE role_id=#{id}
AND tenant_scope='TENANT'
AND tenant_id=#{tenantId}
AND system_role=0
AND status='ACTIVE'
AND version=#{version}

UPDATE t_role
SET status='INACTIVE', version=version+1, update_time=#{now}
WHERE role_id=#{id}
AND tenant_scope='TENANT'
AND tenant_id=#{tenantId}
AND system_role=0
AND status='ACTIVE'
AND version=#{version}

UPDATE t_role_permission
SET status='REVOKED', version=version+1, update_time=#{now}
WHERE role_id=#{roleId}
AND status='ACTIVE'
